<script setup lang="ts">
import { computed,onMounted,ref } from 'vue';import { api,type CmsUser } from '../api'
const props=defineProps<{user:CmsUser|null}>();const staff=computed(()=>['admin','operator'].includes(props.user?.role.toLowerCase()||''));const admin=computed(()=>props.user?.role.toLowerCase()==='admin')
const data=ref<any>(null),detail=ref<any>(null),error=ref(''),notice=ref(''),busy=ref(false),dragging=ref(false),file=ref<File|null>(null);const now=new Date();const form=ref({aggregator:'SoundOn',month:String(now.getMonth()+1).padStart(2,'0'),year:String(now.getFullYear())});const rates=ref<Record<string,number>>({IDR:1});const confirmUnresolved=ref(false)
const years=Array.from({length:15},(_,i)=>String(now.getFullYear()+1-i));const months=['Januari','Februari','Maret','April','Mei','Juni','Juli','Agustus','September','Oktober','November','Desember'];
const money=(v:any)=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(Number(v||0));
async function load(){try{data.value=await api('/api/reports');error.value=''}catch(e){error.value=(e as Error).message}}
function choose(f:File|null){if(!f)return;if(!/\.(xlsx|xls|csv)$/i.test(f.name)){error.value='Format file harus XLSX, XLS, atau CSV.';return}file.value=f;error.value=''}
async function upload(){if(!file.value)return;busy.value=true;notice.value='Membaca file dan mencocokkan UPC/ISRC…';const fd=new FormData();fd.append('aggregator',form.value.aggregator);fd.append('period',`${form.value.year}-${form.value.month}`);fd.append('file',file.value);try{const r=await api<any>('/api/reports/import',{method:'POST',body:fd});notice.value='Report berhasil diproses. Silakan review sebelum finalisasi.';await open(r.batch_id);await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function open(id:number){try{detail.value=await api(`/api/reports/${id}`);rates.value={IDR:1};const currencies=JSON.parse(detail.value.batch.gross_revenue_summary||'[]');for(const c of currencies)if(rates.value[c.currency]===undefined)rates.value[c.currency]=c.currency==='IDR'?1:0}catch(e){error.value=(e as Error).message}}
async function saveRates(){await api(`/api/reports/${detail.value.batch.id}/rates`,{method:'PUT',body:JSON.stringify({rates:rates.value})});notice.value='Kurs disimpan.'}
async function recheck(){busy.value=true;try{await api(`/api/reports/${detail.value.batch.id}/recheck`,{method:'POST'});await open(detail.value.batch.id)}finally{busy.value=false}}
async function finalize(){busy.value=true;error.value='';try{await saveRates();await api(`/api/reports/${detail.value.batch.id}/finalize`,{method:'POST',body:JSON.stringify({confirm_unresolved:confirmUnresolved.value})});notice.value='Report difinalisasi dan royalti telah masuk ke akun user.';detail.value=null;await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
onMounted(load)
</script>
<template><div class="page-heading"><div><div class="eyebrow">REPORT & ROYALTI</div><h1>{{staff?'Report Aggregator':'Royalti Saya'}}</h1><p>{{staff?'Review kepemilikan UPC/ISRC sebelum pendapatan dibagikan.':'Pendapatan yang sudah diverifikasi dan difinalisasi admin.'}}</p></div></div><nav class="report-tabs"><a href="#analitik">Analitik</a><a href="#daftar-report">Report</a><a v-if="admin" href="#import-report">Import Report</a></nav><p v-if="error" class="alert error">{{error}}</p><p v-if="notice" class="alert">{{notice}}</p>
<template v-if="!staff"><section class="royalty-stats"><article><small>Total Royalti</small><strong>{{money(data?.summary?.total_revenue)}}</strong></article><article><small>Total Kuantitas</small><strong>{{data?.summary?.total_quantity||0}}</strong></article><article><small>Jumlah Lagu</small><strong>{{data?.summary?.total_tracks||0}}</strong></article><article><small>Periode Report</small><strong>{{data?.summary?.total_batches||0}}</strong></article></section><section class="panel"><div class="table-scroll"><table><thead><tr><th>Periode</th><th>Lagu</th><th>Platform</th><th>UPC / ISRC</th><th>Kuantitas</th><th>Royalti</th></tr></thead><tbody><tr v-for="r in data?.rows?.data||[]" :key="r.id"><td>{{r.report_period}}</td><td><strong>{{r.track_title||r.release_title}}</strong><small>{{r.artist_name}}</small></td><td>{{r.platform}}</td><td>{{r.upc||'—'}}<small>{{r.isrc||'—'}}</small></td><td>{{r.quantity}}</td><td><strong>{{money(r.user_revenue_idr)}}</strong></td></tr></tbody></table></div><p v-if="!data?.rows?.data?.length" class="empty">Royalti belum tersedia.</p></section></template>
<template v-else><section v-if="admin" class="report-import panel"><div class="report-steps"><div><b>1</b><strong>Import</strong><span>Upload XLSX, XLS, atau CSV</span></div><div><b>2</b><strong>Review</strong><span>Cocokkan UPC dan ISRC</span></div><div><b>3</b><strong>Finalisasi</strong><span>Masukkan royalti user</span></div></div><div class="field-grid"><label>Aggregator<select v-model="form.aggregator"><option v-for="a in ['SoundOn','Believe','The Orchard','FUGA','EVEARA','Loka','Lainnya']" :key="a">{{a}}</option></select></label><label>Periode<div class="period-select"><select v-model="form.month"><option v-for="(m,i) in months" :key="m" :value="String(i+1).padStart(2,'0')">{{m}}</option></select><select v-model="form.year"><option v-for="y in years" :key="y">{{y}}</option></select></div></label></div><label class="report-drop" :class="{dragging}" @dragover.prevent="dragging=true" @dragleave="dragging=false" @drop.prevent="dragging=false;choose($event.dataTransfer?.files[0]||null)"><input type="file" accept=".xlsx,.xls,.csv" @change="choose(($event.target as HTMLInputElement).files?.[0]||null)"/><span class="upload-icon">⇧</span><strong>{{file?.name||'Tarik dan letakkan file report di sini'}}</strong><span>{{file?`${(file.size/1024).toFixed(1)} KB · siap diproses`:'atau klik untuk memilih file'}}</span></label><button class="primary-button" :disabled="!file||busy" @click="upload">{{busy?'Memproses…':'Import & Review'}}</button></section>
<section class="panel"><div class="table-scroll"><table><thead><tr><th>Periode</th><th>Aggregator / File</th><th>Matching</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="b in data?.batches?.data||[]" :key="b.id"><td>{{b.report_period}}</td><td><strong>{{b.aggregator_name}}</strong><small>{{b.original_file_name}}</small></td><td>{{b.matched_rows}} / {{b.total_rows}}<small>{{Number(b.no_account_rows)+Number(b.conflict_rows)+Number(b.invalid_rows)}} belum cocok</small></td><td><span class="pill">{{b.status}}</span></td><td><button class="text-button" @click="open(b.id)">Review</button></td></tr></tbody></table></div></section></template>
<div v-if="detail" class="modal-backdrop" @click.self="detail=null"><div class="modal report-review-modal"><button class="close" @click="detail=null">×</button><div class="eyebrow">REVIEW REPORT</div><h2>{{detail.batch.aggregator_name}} · {{detail.batch.report_period}}</h2><div class="review-summary"><span class="matched">{{detail.batch.matched_rows}} cocok</span><span>{{detail.batch.no_account_rows}} tanpa akun</span><span>{{detail.batch.conflict_rows}} konflik</span><span>{{detail.batch.invalid_rows}} invalid</span></div><div class="rate-grid"><label v-for="(_,currency) in rates" :key="currency">Kurs {{currency}} ke IDR<input v-model.number="rates[currency]" type="number" min="0" step="0.0001"/></label></div><div class="table-scroll review-rows"><table><thead><tr><th>Baris</th><th>Lagu</th><th>UPC / ISRC</th><th>Pemilik</th><th>Status</th><th>Revenue</th></tr></thead><tbody><tr v-for="r in detail.rows.data" :key="r.id"><td>{{r.row_number}}</td><td>{{r.track_title}}<small>{{r.artist_name}}</small></td><td>{{r.upc_original||'—'}}<small>{{r.isrc_original||'—'}}</small></td><td>{{r.owner_name||r.owner_company||'Belum ditemukan'}}<small>{{r.owner_email}}</small></td><td><span class="pill" :class="r.status.toLowerCase()">{{r.status}}</span><small v-if="r.error_message">{{r.error_message}}</small></td><td>{{r.client_payment_currency}} {{r.net_revenue}}</td></tr></tbody></table></div><label class="consent"><input v-model="confirmUnresolved" type="checkbox"/> Finalisasi baris yang cocok dan abaikan baris yang belum terselesaikan.</label><div class="review-actions"><button class="text-button" :disabled="busy" @click="recheck">Cek Ulang UPC/ISRC</button><button v-if="admin&&detail.batch.status==='READY_FOR_REVIEW'" class="primary-button" :disabled="busy" @click="finalize">Finalisasi Royalti</button></div></div></div>
</template>
